// Flujo 01b, nodo "parsear-callback": de la actualización de Telegram (webhook
// del bot) saca acción e id, y comprueba que quien pulsa es el administrador.
// Rechazar con motivo: el admin responde al mensaje del bot con el texto; ese
// mensaje llega como `message` con reply_to_message.
function run(item, env) {
  const u = item.json.body || item.json;
  const admin = String(env.TELEGRAM_ADMIN_CHAT_ID || "");

  if (u.callback_query) {
    const cq = u.callback_query;
    const chatId = String(cq.message && cq.message.chat && cq.message.chat.id);
    const m = /^(approve|reject):([0-9a-f-]{36})$/.exec(cq.data || "");
    return [{
      json: {
        kind: "callback",
        valid: chatId === admin && Boolean(m),
        reason: chatId !== admin ? "chat no autorizado" : !m ? "callback_data desconocido" : null,
        action: m ? m[1] : null,
        restaurantId: m ? m[2] : null,
        chatId,
        messageId: cq.message && cq.message.message_id,
        callbackQueryId: cq.id,
        from: cq.from && (cq.from.first_name || cq.from.username),
        originalText: cq.message && cq.message.text,
      },
    }];
  }

  if (u.message && u.message.reply_to_message) {
    const msg = u.message;
    const chatId = String(msg.chat && msg.chat.id);
    const replied = msg.reply_to_message.text || "";
    const m = /Motivo de rechazo para ([0-9a-f-]{36})/.exec(replied);
    const reason = String(msg.text || "").trim();
    return [{
      json: {
        kind: "reject-reason",
        valid: chatId === admin && Boolean(m) && reason.length >= 10,
        reason: chatId !== admin ? "chat no autorizado" : !m ? "respuesta a un mensaje que no pide motivo" : reason.length < 10 ? "motivo demasiado corto (mínimo 10 caracteres)" : null,
        action: "reject",
        restaurantId: m ? m[1] : null,
        rejectReason: reason,
        chatId,
        messageId: msg.message_id,
        from: msg.from && (msg.from.first_name || msg.from.username),
      },
    }];
  }

  return [{ json: { kind: "ignored", valid: false, reason: "actualización sin callback ni respuesta", chatId: null } }];
}

return run($input.first(), $env); // @n8n-invoke

// Flujo 01b, nodo "pedir-motivo": el admin ha pulsado Rechazar; se le pide el
// motivo respondiendo a un mensaje que lleva el id (así la respuesta se puede
// asociar sin estado).
// Compartido: cuerpos para la Bot API de Telegram (parse_mode HTML).
// @exports escapeHtml, tgMessage, tgEditMessage, splitTelegram

function escapeHtml(s) {
  return String(s == null ? "" : s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
}

/** Cuerpo de sendMessage. buttons: [[{text, data}]] → teclado inline. */
function tgMessage(chatId, html, buttons) {
  const body = { chat_id: chatId, text: html, parse_mode: "HTML", disable_web_page_preview: true };
  if (buttons && buttons.length) {
    body.reply_markup = { inline_keyboard: buttons.map((row) => row.map((b) => ({ text: b.text, callback_data: b.data }))) };
  }
  return body;
}

/** Cuerpo de editMessageText (quita los botones al confirmar una acción). */
function tgEditMessage(chatId, messageId, html) {
  return { chat_id: chatId, message_id: messageId, text: html, parse_mode: "HTML", disable_web_page_preview: true, reply_markup: { inline_keyboard: [] } };
}

/** Telegram limita a 4096 caracteres: parte por párrafos. */
function splitTelegram(text, max) {
  const limit = max || 4000;
  if (text.length <= limit) return [text];
  const chunks = [];
  let current = "";
  for (const para of text.split(/\n\n+/)) {
    if ((current + "\n\n" + para).length > limit && current) {
      chunks.push(current);
      current = para;
    } else current = current ? current + "\n\n" + para : para;
  }
  if (current) chunks.push(current);
  return chunks.flatMap((c) => (c.length <= limit ? [c] : c.match(new RegExp(`[\\s\\S]{1,${limit}}`, "g"))));
}
function run(cbItem) {
  const cb = cbItem.json;
  const text = `Motivo de rechazo para ${cb.restaurantId}\n\nResponde a este mensaje con el motivo (mínimo 10 caracteres). El dueño lo recibirá tal cual.`;
  return [{
    json: {
      ...cb,
      askBody: { chat_id: cb.chatId, text, reply_markup: { force_reply: true, selective: true } },
      answerBody: cb.callbackQueryId ? { callback_query_id: cb.callbackQueryId, text: "Escribe el motivo" } : null,
    },
  }];
}

return run($input.first()); // @n8n-invoke

// Flujo 01b, nodo "confirmar-accion": tras llamar a la API de Foodzinder
// (o fallar), prepara la edición del mensaje original y la respuesta al botón.
// Compartido: cuerpos para la Bot API de Telegram (parse_mode HTML).
// @exports escapeHtml, tgMessage, tgEditMessage, splitTelegram

function escapeHtml(s) {
  return String(s == null ? "" : s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
}

